def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            for k in range(N):
                l = i + j - k
                if l < 0 or l >= N or grid[i][j] == 0 or grid[k][l] == 0:
                    continue
                if i > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[k][l] * (i != k))
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + grid[k][l] * (i != k))
                if j > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[i][j] + grid[k][l] * (j != l))
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j] + grid[k][l] * (j != l))

    return max(0, dp[N-1][N-1][N-1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-1] * N for _ in range(N)] for _ in range(N)]

    # Base case
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(max(0, j-i), min(N, j+i+1)):
                l = j - i + k
                if i > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[l][k])
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + (grid[l][k] if k != j else 0))
                if k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + (grid[i][j] if i != l else 0) + grid[l][k])
                dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + (grid[i][j] + grid[l][k] if i != l or j != k else grid[i][j]))

    return dp[N-1][N-1][N-1] if dp[N-1][N-1][N-1] != -1 else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
