def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[[-1] * (N+1) for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]
    dp[1][1][1][1] = grid[0][0]

    def solve(x1, y1, x2, y2):
        if x1 > N or y1 > N or x2 > N or y2 > N:
            return float('-inf')
        if dp[x1][y1][x2][y2] != -1:
            return dp[x1][y1][x2][y2]
        if x1 == N and y1 == N:
            return grid[N-1][N-1]
        val = grid[x1-1][y1-1] if (x1, y1) == (x2, y2) else grid[x1-1][y1-1] + grid[x2-1][y2-1]
        dp[x1][y1][x2][y2] = val + max(
            solve(x1+1, y1, x2+1, y2),
            solve(x1+1, y1, x2, y2+1),
            solve(x1, y1+1, x2+1, y2),
            solve(x1, y1+1, x2, y2+1)
        )
        return dp[x1][y1][x2][y2]

    return solve(1, 1, 1, 1)

