def find_number_combinations():
    def is_unique(n1, n2, n3):
        str_n1, str_n2, str_n3 = str(n1), str(n2), str(n3)
        return len(set(str_n1 + str_n2 + str_n3)) == 9

    result = []
    for n in range(123, 334):  # The first number can't be more than 333 as 3*333=999
        n2 = 2 * n
        n3 = 3 * n
        if n2 > 999 or n3 > 999:
            break
        if is_unique(n, n2, n3):
            result.append((n, n2, n3))
    return sorted(result)

