def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)

    def split_and_multiply(start, k):
        if k == 0:
            return int(num_str[start:])
        max_product = 0
        for i in range(start + 1, N - k + 1):
            left = int(num_str[start:i])
            right = split_and_multiply(i, k - 1)
            max_product = max(max_product, left * right)
        return max_product

    return split_and_multiply(0, K)

def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)

    max_product = 0
    for i in range(1, N):
        left_part = int(num_str[:i])
        right_part = num_str[i:]
        if K == 1:
            current_product = left_part * int(right_part)
        else:
            current_product = left_part * max_product(right_part, len(right_part), K - 1)
        if current_product > max_product:
            max_product = current_product

    return max_product

