    def dfs(start, k):
        if k == 0:
            return int(num_str[start:])
        max_val = 0
        for i in range(start + 1, N - k + 2):
            current Product = int(num_str[start:i])
            max_val = max(max_val, current_product * dfs(i, k - 1))
        return max_val

    return dfs(0, K)

def max_product(num_str: str, N: int, K: int) -> int:
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    if K == 0:
        return int(num_str)

    max_product = 0
    from itertools import combinations

    # Generate all possible positions to insert multiplication signs
    positions = list(range(1, N))
    for comb in combinations(positions, K):
        parts = []
        last = 0
        for pos in comb:
            parts.append(num_str[last:pos])
            last = pos
        parts.append(num_str[last:])
        max_product = max(max_product, split_and_multiply(parts))

    return max_product

def max_product(num_str: str, N: int, K: int) -> int:
    def dp(i, k):
        if k == 0:
            return int(num_str[i:])
        max_val = 0
        for j in range(i + 1, N - k + 1):
            current_product = int(num_str[i:j]) * dp(j, k - 1)
            max_val = max(max_val, current_product)
        return max_val

    return dp(0, K)

