def max_energy(beads):
    n = len(beads)
    beads = beads + beads[:n-1]  # Extend the beads to handle circular nature

    # dp[i][j] will hold the maximum energy obtainable by merging beads between i and j
    dp = [[0] * (2*n) for _ in range(2*n)]

    for length in range(2, n+1):
        for i in range(n):
            j = i + length - 1
            for k in range(i+1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return max(dp[i][i+n-1] for i in range(n))

def max_energy(beads):
    n = len(beads)
    beads = [0] + beads + [beads[0]]  # Adding virtual beads to handle circular nature
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    for length in range(2, n + 2):
        for i in range(1, n + 2 - length + 1):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[1][n + 1]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Extend the beads to handle the circular nature
    beads_extended = beads + beads

    # dp[i][j] represents the maximum energy obtainable from merging beads_extended[i:j+1]
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads_extended[i] * beads_extended[k] * beads_extended[j])

    # The maximum energy will be the maximum value in dp[i][i+n-1] for all i
    return max(dp[i][i + n - 1] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        coeff_str = str(abs(coeff)) if abs(coeff) != 1 or degree == 0 else ''
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        terms.append(f'{sign}{coeff_str}{var_str}')
    if not terms:
        return '0'
    if terms[0].startswith('+'):
        terms[0] = terms[0][1:]
    return ''.join(terms)

