def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    def is_coprime(a, b):
        return gcd(a, b) == 1

    count = 0
    quotient = y0 // x0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if is_coprime(a, b):
                if a == b:
                    count += 1
                else:
