    for participant, stmts in statements.items():
        for stmt in stmts:
            if any(day in stmt for day in days_of_week):
                continue
            is_liar = participant in liar_count
            if "guilty" in stmt:
                if (participant == scenario and not is_liar) or (participant != scenario and is_liar):
                    continue
                else:
                    return False
            elif "not guilty" in stmt:
                if (participant == scenario and is_liar) or (participant != scenario and not is_liar):
