        if c.islower():
            return chr((ord(c) - ord('a') - (ord(k.lower()) - ord('a'))) % 26 + ord('a'))
        else:
            return chr((ord(c) - ord('A') - (ord(k.upper()) - ord('A'))) % 26 + ord('A'))

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
