def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    # Initialize arrays to store the length of increasing and decreasing subsequences
    inc = [1] * n
    dec = [1] * n

    # Fill the increasing subsequence array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill the decreasing subsequence array
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if heights[i] > heights[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Calculate the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, inc[i] + dec[i] - 1)

    # The minimum number of students to leave
    return n - max_choir_length

